@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Get the vertices from the resultMap
    Set<V> vertices = new HashSet<>(resultMap.values());

    // Split the vertices into two sets for the bipartite graph
    Set<V> set1 = new HashSet<>();
    Set<V> set2 = new HashSet<>();
    int count = 0;
    for (V vertex : vertices) {
        if (count % 2 == 0) {
            set1.add(vertex);
        } else {
            set2.add(vertex);
        }
        count++;
    }

    // Add edges between the two sets to make the graph complete bipartite
    for (V v1 : set1) {
        for (V v2 : set2) {
            target.addEdge(v1, v2);
        }
    }

    // Add the vertices to the resultMap
    for (V vertex : vertices) {
        resultMap.put(vertex.toString(), vertex);
    }
}
