private void pop(final String descriptor) {
    int count = 1;
    if (descriptor.charAt(0) == '(') {
        int balance = 1;
        for (int i = 1; i < descriptor.length(); i++) {
            char c = descriptor.charAt(i);
            if (c == '(') balance++;
            else if (c == ')') balance--;
            else if (c == 'L' || c == '[') {
                while (descriptor.charAt(i) != ';') i++;
            }
            if (balance == 0) {
                count = i - count + 1;
                break;
