private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList() {
    List<Pair<List<Pair<Integer,Integer>>,E>> globalSeparatorList = new ArrayList<>();
    for (E edge : graph.edges()) {
        List<Pair<Integer,Integer>> localSeparatorList = new ArrayList<>();
        for (int v : graph.adjacentVertices(edge)) {
            for (int w : graph.adjacentVertices(edge)) {
                if (v != w && !graph.hasEdge(v, w)) {
                    List<Integer> separator = findMinimalSeparator(v, w);
                    localSeparatorList.add(new Pair<>(separator, edge));
                }
            }
        }
        globalSeparatorList.addAll(localSeparatorList);
    }
    return globalSeparatorList;
}

private List<Integer> findMinimalSeparator(int v, int w) {
    Set<Integer> separator = new HashSet<>();
    for (int u : graph.adjacentVertices(v)) {
        if (u != w && graph.hasEdge(u, w)) {
            separator.add(u);
        }
    }
    return new ArrayList<>(separator);
}
