public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null || pane == null) {
        return;
    }

    // Select the row in the JTable
    table.setRowSelectionInterval(row, row);

    // Get the vertical scroll bar of the JScrollPane
    JScrollBar scrollBar = pane.getVerticalScrollBar();

    // Get the bounds of the selected row
    Rectangle rowBounds = table.getCellRect(row, 0, true);

    // Scroll the JScrollPane to make the selected row visible
    scrollBar.setValue(rowBounds.y);

    // Repaint the JTable later to ensure the newly selected row is painted
    SwingUtilities.invokeLater(() -> table.repaint());
