private void pop(final String descriptor) {
    int count = 1;
    if (descriptor.startsWith("(")) {
        int balance = 1;
        for (int i = 1; i < descriptor.length(); i++) {
            char c = descriptor.charAt(i);
            if (c == '(') balance++;
            else if (c == ')') balance--;
            else if (c == 'L' || c == '[') {
                while (descriptor.charAt(i) != ';') i++;
            } else if (balance == 0) {
                count++;
            }
        }
    }
    for (int i = 0; i < count; i++) {
        outputFrameStack.pop();
    }
}
